<?php
if ( ! defined( 'ABSPATH' ) ) { exit; }

function kimpu_register_responsive_controls( $customizer ) {
	$section = 'kimpu_design_responsive'; $customizer->add_section( $section, array( 'title' => __( 'Responsive Design', 'kimpu-multipurpose' ), 'panel' => 'kimpu_global_design', 'priority' => 80, 'description' => __( 'The theme uses fixed mobile (767px), tablet (768–1023px), and desktop (1024px+) breakpoints.', 'kimpu-multipurpose' ) ) );
	$fields = array( 'container_padding_desktop' => array( 20, 10, 80, __( 'Desktop Container Padding (px)', 'kimpu-multipurpose' ) ), 'container_padding_tablet' => array( 24, 10, 60, __( 'Tablet Container Padding (px)', 'kimpu-multipurpose' ) ), 'container_padding_mobile' => array( 15, 10, 40, __( 'Mobile Container Padding (px)', 'kimpu-multipurpose' ) ), 'mobile_body_size' => array( 16, 13, 22, __( 'Mobile Body Size (px)', 'kimpu-multipurpose' ) ), 'mobile_section_spacing' => array( 56, 32, 120, __( 'Mobile Section Spacing (px)', 'kimpu-multipurpose' ) ) );
	foreach ( $fields as $key => $data ) { $id = 'kimpu_design_' . $key; if ( $customizer->get_setting( $id ) ) { continue; } $customizer->add_setting( $id, array( 'default' => $data[0], 'sanitize_callback' => function( $v ) use ( $data ) { return (int) kimpu_sanitize_design_number( $v, $data[1], $data[2] ); }, 'transport' => 'refresh' ) ); $customizer->add_control( $id, array( 'label' => $data[3], 'section' => $section, 'type' => 'number', 'input_attrs' => array( 'min' => $data[1], 'max' => $data[2] ) ) ); }
	$customizer->add_setting( 'kimpu_design_mobile_heading_scale', array( 'default' => .86, 'sanitize_callback' => function( $v ) { return kimpu_sanitize_design_number( $v, .65, 1 ); }, 'transport' => 'refresh' ) ); $customizer->add_control( 'kimpu_design_mobile_heading_scale', array( 'label' => __( 'Mobile Heading Scale', 'kimpu-multipurpose' ), 'section' => $section, 'type' => 'number', 'input_attrs' => array( 'min' => .65, 'max' => 1, 'step' => .01 ) ) );
	$customizer->add_setting( 'kimpu_design_mobile_button_width', array( 'default' => 'auto', 'sanitize_callback' => function( $v ) { return kimpu_sanitize_design_choice( $v, array( 'auto', 'full' ), 'auto' ); }, 'transport' => 'refresh' ) ); $customizer->add_control( 'kimpu_design_mobile_button_width', array( 'label' => __( 'Mobile Button Width', 'kimpu-multipurpose' ), 'section' => $section, 'type' => 'select', 'choices' => array( 'auto' => __( 'Content Width', 'kimpu-multipurpose' ), 'full' => __( 'Full Width', 'kimpu-multipurpose' ) ) ) );
}
